#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <errno.h>

static long long absolute_ll(long long v)
{
    return v < 0 ? -v : v;
}

static long long gcd_ll(long long a, long long b)
{
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

static long long lcm_ll(long long a, long long b, long long g)
{
    return (a / g) * b;
}

static int parse_number(const char *s, long long *out)
{
    char *endptr = NULL;
    errno = 0;
    long long v = strtoll(s, &endptr, 10);
    if (endptr == s) return 1;
    if (*endptr != '\0') return 1;
    if (errno == ERANGE) return 1;
    *out = v;
    return 0;
}

int main(int argc, char **argv)
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    long long a_raw, b_raw;
    if (parse_number(argv[1], &a_raw) || parse_number(argv[2], &b_raw)) {
        puts("BAD_INPUT");
        return 0;
    }
    if (a_raw == LLONG_MIN || b_raw == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }
    long long a = absolute_ll(a_raw);
    long long b = absolute_ll(b_raw);
    const long long LIMIT = 1000000LL;
    if (a > LIMIT || b > LIMIT) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (a == 0 && b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }
    long long g = gcd_ll(a, b);
    long long l = lcm_ll(a, b, g);
    printf("gcd=%ld lcm=%ld\n", g, l);
    return 0;
}
